  (4098, 19537, 'Gai ningkoo'' ta'' sedi suang.', 'sedi', 'Mereka duduk di tepi sungai.', 'They sat at the riverbank.', NULL),
  (4100, 19540, 'Aku selalu nguse’ nguse-an', 'selalu', 'basuh', 'I always wash (my) hands before eating.', NULL),
  (4101, 19559, 'A. Sian boi', 'sian', 'ayam', 'Azizy bought the chicken(s).', NULL),
  (4102, 19559, '* Ta’ Pirik sian boi', 'sian', 'siapa', 'Who sent the bread to Pirik?', NULL),
  (4103, 19562, 'Sikot no ellaw, uun', 'sikot', 'apabila, dekat, siapa', 'When it was near daylight, those who had gone out now arrived.', NULL),
  (4104, 19566, 'Iyo mebeli diki''-ni sinsim amas.', 'sinsim', 'Dia membelikan adiknya sebentuk cincin emas.', 'He bought his younger sibling a gold ring.', NULL),
  (4105, 19566, 'Sinsim tu nianang le'' moto-ku ta'' lantai.', 'sinsim', 'Cincin ini dijumpai oleh saya di atas lantai.', 'This ring was found by my eyes on the floor.', NULL),
  (4106, 19576, 'Bése'' lumua'' lua'' moto-ni masa iyo nangis.', 'suang', 'Air mata mengalir dari matanya semasa dia menangis.', 'Tears flowed from his eyes while he was crying.', NULL),
  (4107, 19576, 'Gai ngeta suang makai biduk diki''.', 'suang', 'Mereka menyeberang sungai menggunakan sampan kecil.', 'They crossed the river using a small boat.', NULL),
  (4108, 19576, 'Suang jomo teko diom majlis e.', 'suang', 'Ramai orang datang ke majlis itu.', 'Many people arrived at the gathering.', NULL),
  (4109, 19576, 'Iyo lumaan en-diam taun sampai teko ta'' suang.', 'suang', 'Dia berjalan di dalam hutan sehingga tiba di sebatang sungai.', 'He walked through the forest until he reached a river.', NULL),
  (4110, 19576, 'Bu''e'' suang tu lumaan terus sampai ta'' laut.', 'suang', 'Air sungai itu mengalir terus sampai ke laut.', 'The river water flows continuously into the sea.', NULL),
